def iade_al(self, kitap_id, tarih):
    """Kitabın iadesini alır ve ödünç kaydını döndürür. Kitap ödünçte değilse ValueError."""
    kayit = self._aktif(kitap_id)
    if kayit is None:
        raise ValueError("kitap ödünçte değil")

    kayit.iade = tarih
    self._ceza_hesapla(kayit)
    return kayit

def _ceza_hesapla(self, kayit):
    if not kayit.iade:
        return

    gun_farki = (kayit.iade - kayit.alinma).days
    gecikme = max(0, gun_farki - 14)

    if gecikme <= 0:
        kayit.ceza = 0.0
        return

    # İlk 7 gün için 2.50 TL, sonraki günler için 5.00 TL
    if gecikme <= 7:
        ceza_toplam = gecikme * 2.50
    else:
        ceza_toplam = (7 * 2.50) + ((gecikme - 7) * 5.00)

    # Üst sınır 150 TL
    if ceza_toplam > 150:
        ceza_toplam = 150.0

    # Öğrenci indirimi %50
    uye = self.uyeler[kayit.uye_id]
    if uye.tur == "ogrenci":
        ceza_toplam *= 0.5

    kayit.ceza = round(ceza_toplam, 2)

def toplam_ceza(self, uye_id):
    """Üyenin iade edilmiş tüm ödünçlerinin cezaları toplamı."""
    return sum(k.ceza for k in self.kayitlar if k.uye_id == uye_id and k.iade is not None)

